import { Minus, Plus } from 'lucide-react'
import * as React from 'react'

import { useControllableState } from '~/hooks/use-controllable-state'
import { cx } from '~/lib/cx'
import styles from './number-input.module.scss'

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

function round(value: number, precision: number) {
  const factor = 10 ** precision
  return Math.round(value * factor) / factor
}

export interface NumberInputProps {
  value?: number
  defaultValue?: number
  onChange?: (value: number) => void
  min?: number
  max?: number
  step?: number
  precision?: number
  disabled?: boolean
  label?: string
  suffix?: string
  className?: string
  id?: string
}

export function NumberInput({
  value,
  defaultValue = 0,
  onChange,
  min = Number.NEGATIVE_INFINITY,
  max = Number.POSITIVE_INFINITY,
  step = 1,
  precision = 0,
  disabled = false,
  label,
  suffix,
  className,
  id,
}: NumberInputProps) {
  const [current, setCurrent] = useControllableState({
    value,
    defaultValue,
    onChange,
  })
  const [draft, setDraft] = React.useState<string | null>(null)
  const generatedId = React.useId()
  const inputId = id ?? generatedId
  const display = draft ?? String(current)

  const commit = (next: number) => {
    const bounded = clamp(round(next, precision), min, max)
    setCurrent(bounded)
    setDraft(null)
  }

  const nudge = (direction: 1 | -1) => {
    if (disabled) return
    commit(current + step * direction)
  }

  return (
    <div className={cx(styles.root, className)}>
      {label ? (
        <label htmlFor={inputId} className={styles.label}>
          {label}
        </label>
      ) : null}

      <div className={cx(styles.shell, disabled && styles.disabled)}>
        <button
          type="button"
          onClick={() => nudge(-1)}
          disabled={disabled || current <= min}
          aria-label="Decrease"
          className={cx(styles.step, styles.decrement)}
        >
          <Minus aria-hidden />
        </button>

        <div className={styles.field}>
          <input
            id={inputId}
            value={display}
            onChange={(event) => setDraft(event.target.value)}
            onBlur={() => {
              const parsed = Number.parseFloat(display)
              commit(Number.isFinite(parsed) ? parsed : current)
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.currentTarget.blur()
              } else if (event.key === 'ArrowUp') {
                event.preventDefault()
                nudge(1)
              } else if (event.key === 'ArrowDown') {
                event.preventDefault()
                nudge(-1)
              }
            }}
            disabled={disabled}
            inputMode="decimal"
            aria-label={label ? undefined : 'Number value'}
            className={styles.control}
          />
          {suffix ? (
            <span className={styles.suffix} aria-hidden>
              {suffix}
            </span>
          ) : null}
        </div>

        <button
          type="button"
          onClick={() => nudge(1)}
          disabled={disabled || current >= max}
          aria-label="Increase"
          className={cx(styles.step, styles.increment)}
        >
          <Plus aria-hidden />
        </button>
      </div>
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  min-width: 0;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
}

.shell {
  display: flex;
  align-items: stretch;
  height: vz.space(9);
  overflow: hidden;
  border: 1px solid vz.color('input');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  box-shadow: vz.elevation(1);
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 3px vz.color('ring', 0.18);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.disabled {
  background: vz.color('muted');
  opacity: 0.6;
  pointer-events: none;
}

.step {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(9);
  padding: 0;
  border: 0;
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  svg {
    @include vz.icon(3.5);
  }

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('accent-foreground');
  }

  @include vz.focus-ring(2px, -2px, 0.6);

  @include vz.disabled {
    opacity: 0.4;
    pointer-events: none;
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.decrement {
  border-right: 1px solid vz.color('border');
}

.increment {
  border-left: 1px solid vz.color('border');
}

.field {
  position: relative;
  display: flex;
  flex: 1;
  align-items: center;
  min-width: 0;
}

.control {
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0 vz.space(2);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-variant-numeric: tabular-nums;
  text-align: center;
  outline: none;

  @include vz.disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }
}

.suffix {
  flex: none;
  padding-right: vz.space(2);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}
